"""Unit tests for teal_activation_magnitude_masks — CPU only, uses mini_llama."""

import os
import sys

import torch
import pytest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from evaluate import teal_activation_magnitude_masks, vanilla_teal_global_masks

MINI_LLAMA = os.path.join(os.path.dirname(__file__), "mini_llama")
DEVICE = torch.device("cpu")


@pytest.fixture(scope="module")
def model():
    from transformers import AutoModelForCausalLM
    m = AutoModelForCausalLM.from_pretrained(MINI_LLAMA, torch_dtype=torch.float32)
    m.eval()
    return m


@pytest.fixture(scope="module")
def calib_data():
    torch.manual_seed(42)
    return torch.randint(0, 128256, (4, 32))


class TestMaskShape:
    def test_returns_dict_for_all_layers(self, model, calib_data):
        masks = teal_activation_magnitude_masks(model, [calib_data[:2], calib_data[2:]], 0.5, DEVICE)
        assert len(masks) == model.config.num_hidden_layers

    def test_mask_shape_matches_intermediate_size(self, model, calib_data):
        masks = teal_activation_magnitude_masks(model, [calib_data], 0.5, DEVICE)
        for mask in masks.values():
            assert mask.shape == (model.config.intermediate_size,)

    def test_mask_is_binary(self, model, calib_data):
        masks = teal_activation_magnitude_masks(model, [calib_data], 0.5, DEVICE)
        for mask in masks.values():
            assert set(mask.unique().tolist()).issubset({0.0, 1.0})


class TestSparsity:
    @pytest.mark.parametrize("target", [0.3, 0.5, 0.7])
    def test_sparsity_near_target(self, model, calib_data, target):
        masks = teal_activation_magnitude_masks(model, [calib_data], target, DEVICE)
        total = sum(m.numel() for m in masks.values())
        zeros = sum((m == 0).sum().item() for m in masks.values())
        actual = zeros / total
        assert abs(actual - target) < 0.05, f"Expected ~{target}, got {actual}"

    def test_zero_sparsity_keeps_all(self, model, calib_data):
        masks = teal_activation_magnitude_masks(model, [calib_data], 0.0, DEVICE)
        for mask in masks.values():
            assert mask.sum() == mask.numel()

    def test_high_sparsity_prunes_most(self, model, calib_data):
        masks = teal_activation_magnitude_masks(model, [calib_data], 0.95, DEVICE)
        total = sum(m.numel() for m in masks.values())
        zeros = sum((m == 0).sum().item() for m in masks.values())
        assert zeros / total > 0.9


class TestDeterminism:
    def test_same_data_same_masks(self, model, calib_data):
        m1 = teal_activation_magnitude_masks(model, [calib_data], 0.5, DEVICE)
        m2 = teal_activation_magnitude_masks(model, [calib_data], 0.5, DEVICE)
        for idx in m1:
            assert torch.equal(m1[idx], m2[idx])


class TestDataloaderFormats:
    def test_dict_batches(self, model, calib_data):
        dl = [{"input_ids": calib_data[:2]}, {"input_ids": calib_data[2:]}]
        masks = teal_activation_magnitude_masks(model, dl, 0.5, DEVICE)
        assert len(masks) == model.config.num_hidden_layers

    def test_tuple_batches(self, model, calib_data):
        dl = [(calib_data[:2],), (calib_data[2:],)]
        masks = teal_activation_magnitude_masks(model, dl, 0.5, DEVICE)
        assert len(masks) == model.config.num_hidden_layers

    def test_single_sequence_1d(self, model, calib_data):
        dl = [calib_data[0]]  # 1-D tensor
        masks = teal_activation_magnitude_masks(model, dl, 0.5, DEVICE)
        assert len(masks) == model.config.num_hidden_layers


class TestConsistencyWithVanillaTeal:
    def test_same_masks_as_vanilla(self, model, calib_data):
        """Both functions use the same importance and allocation, so masks must match."""
        actmag = teal_activation_magnitude_masks(model, [calib_data], 0.5, DEVICE)
        vanilla = vanilla_teal_global_masks(model, calib_data, 0.5, calib_batch_size=4)
        for idx in actmag:
            assert torch.equal(actmag[idx], vanilla[idx]), f"Layer {idx} masks differ"


class TestForwardRestored:
    def test_model_output_unchanged(self, model, calib_data):
